// pos-restock — Modul 4: Validator (liest nicht mehr, prueft nur noch)
// Input:  extrakt   = JSON-String aus dem Claude-Call
//         datum     = Belegdatum aus Belege.Datum, ueber Modul 101
// Output: result.ok / .ul / .datum / .store / .kundennr / .art / .person
//         .positionen[] / .inventar[]
//         .fehler[]   -> blockt den Lauf (Kaskade in Modul 43)
//         .hinweise[] -> blockt NICHT, dokumentiert nur
//         .fehlertext / .notiz / .dupText -> fertige Strings fuer ⚙ Fehler,
//         damit die Update-Module ohne IML-Stringverkettung auskommen.
//
// Rueckholungen werden mit negativem Vorzeichen gebucht. Das Vorzeichen
// entsteht AUSSCHLIESSLICH aus der Belegart — Belege drucken immer positive
// Mengen. Deshalb blockt eine unklare Belegart hart: sie waere sonst ein
// stiller Vorzeichenfehler.

const errors  = [];
const hints = [];

const empty = () => ({ ok: false, ul: null, date: null, store: null,
                      customer_no: "", kind: null, person: null,
                      positions: [], fixtures: [], errors: errors, hints: hints,
                      signature: "unklar", signed: false,
                      errorText: errors.join(" · "), note: "", dupText: "" });

// ── 1) JSON einlesen ────────────────────────────────────────────────────────
let d;
try {
  d = typeof input.extract === "string" ? JSON.parse(input.extract) : input.extract;
} catch (e) {
  errors.push("Antwort ist kein gueltiges JSON: " + e.message);
  return empty();
}
if (!d || typeof d !== "object") { errors.push("Leere Antwort"); return empty(); }

// ── 2) Belegart ─────────────────────────────────────────────────────────────
// Das Modell liefert die Art nur, wenn Ueberschrift UND Uebergabe-/Abhol-Label
// dasselbe sagen — bei Widerspruch null. Ein falsch erkannter Belegtyp dreht in
// Deploy B das Vorzeichen; deshalb blockt null hier hart.
const KINDS = ["Übergabe", "Rückholung"];
const kind = KINDS.includes(d.kind) ? d.kind : null;
if (!kind) {
  errors.push("Belegart nicht eindeutig — Ueberschrift und Uebergabe-/Abhol-Zeile " +
           "widersprechen sich oder fehlen");
}

const isReturn = kind === "Rückholung";
const sign = isReturn ? -1 : 1;

// ── 3) Kopfdaten ────────────────────────────────────────────────────────────
// Das Praefix haengt vom Belegalter ab (UL neu, AF alt) — geprueft wird die
// STRUKTUR, nicht ein bestimmtes Praefix. Ein Fehlgriff des Parsers (Adress-
// oder Betragszeile) scheitert hier weiterhin.
const ul = d.ul || null;
if (!ul) errors.push("Belegnummer fehlt");
else if (!/^[A-Z]{2,3}-\d+-\d+$/.test(ul))
  errors.push(`Belegnummer hat unerwartetes Format: ${ul}`);

const store = d.store || null;
if (!store) errors.push("Store (Empfaenger) fehlt");

// Kunden-Nr. ist der primaere Store-Schluessel (Modul 34, Stufe 1). Sie steht
// auf BEIDEN Belegarten in der Kopfzeile — anders als die Kommissionaer-Zeile,
// die es nur auf dem Uebergabeprotokoll gibt. Fehlt sie, bleibt der
// Namensabgleich als Stufe 2; deshalb Hinweis statt Fehler.
const customer_no = String(d.customer_no == null ? "" : d.customer_no).replace(/\D/g, "");
if (!customer_no) hints.push("Kunden-Nr. nicht lesbar — Store wird ueber den Namen aufgeloest");

// Uebergeben/abgeholt durch: einzige Quelle fuer den Vertriebler. Der Name
// steuert ueber Besteuerung und Kondition den Kostenanteil — kein Default,
// kein Fallback auf ein handgesetztes Feld.
const person = String(d.person == null ? "" : d.person).trim() || null;
if (!person) {
  errors.push(kind === "Rückholung"
    ? "\"Abgeholt durch\" nicht lesbar — Vertriebler nicht bestimmbar"
    : "\"Uebergeben durch\" nicht lesbar — Vertriebler nicht bestimmbar");
}

// Belegdatum: kommt aus Belege.Datum, NICHT mehr aus dem Dokument.
// Der Dispatcher hat es gedruckt gelesen, normalisiert gegengeprueft und dort
// abgelegt — es ist die einzige Quelle fuer das Leistungsdatum und waehlt damit
// Kondition und Preis. Hier nur noch hart auf YYYY-MM-DD ziehen: ein ISO-Wert
// mit Zeitzone wuerde von Airtable als UTC gelesen und als Vortag gespeichert.
// Fehlt oder faellt es aus dem Format, blockt der Lauf — raten ist hier verboten.
let date = null;
const dateRaw = String(input.date == null ? "" : input.date).trim();
if (dateRaw) {
  const t = dateRaw.split("T")[0].match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (t) date = `${t[1]}-${t[2]}-${t[3]}`;
}
if (!date)
  errors.push(`Belegdatum fehlt oder unlesbar: "${dateRaw}" — Beleg-Datensatz pruefen`);

// ── 3b) Unterschrift: reine Anwesenheitspruefung ────────────────────────────
// Drei Zustaende statt Boolean — "unsicher" wuerde als false still zu
// "nicht unterschrieben" werden. Blockt bewusst NICHT (Hinweis, kein Fehler).
// Rueckholprotokolle haben keine Unterschriftsseite — dort ist "unklar" der
// Normalzustand und kein meldenswerter Befund.
const SIG_STATES = ["vorhanden", "fehlt", "unklar"];
const signature  = SIG_STATES.includes(d.signature) ? d.signature : "unklar";
const signed = signature === "vorhanden";

if (!isReturn) {
  if (signature === "fehlt")  hints.push("Unterschrift fehlt");
  if (signature === "unklar") hints.push("Unterschrift nicht sicher erkennbar");
}

// ── 4) Positionen sortieren ─────────────────────────────────────────────────
const all = Array.isArray(d.positions) ? d.positions : [];
if (all.length === 0) errors.push("keine Positionen extrahiert");

// Lueckenlos ab 1 — ueber ALLE Zeilen inkl. Inventar, sonst faellt eine
// fehlende Zeile nicht auf.
all.forEach((p, i) => {
  if (p.pos !== i + 1)
    errors.push(`Position ${p.pos} an Stelle ${i + 1} — Zeile fehlt oder Reihenfolge gestoert`);
});

// Buchstaben-Praefix = Ausstattung (POS-Display o.ae.), kein Kommissionsgut.
const isFixture = no => /^[A-Z]/.test(String(no || ""));

const positions = [];
const fixtures   = [];

all.forEach(p => {
  const no = String(p.no || "").trim();
  if (!no) { errors.push(`Pos ${p.pos}: Artikelnummer fehlt`); return; }
  (isFixture(no) ? fixtures : positions).push({
    pos: p.pos, no, label: p.label, qty: p.qty, kg: p.kg, grams: p.grams
  });
});

// ── 5) Gewicht: pruefen ODER ableiten, nur auf Kommissionsware ────────────────
// Alle Mengenpruefungen laufen auf Betraegen. Belege drucken immer positive
// Mengen; das Vorzeichen entsteht erst beim Buchen (Deploy B) und darf die
// Kreuzprobe nicht kippen.
positions.forEach(p => {
  if (typeof p.qty !== "number") {
    errors.push(`Pos ${p.pos} (${p.no}): Menge fehlt`); return;
  }
  if (typeof p.grams !== "number") {
    errors.push(`Pos ${p.pos} (${p.no}): Grammatur nicht aus der Bezeichnung lesbar`); return;
  }
  if (p.qty < 0 || (typeof p.kg === "number" && p.kg < 0)) {
    errors.push(`Pos ${p.pos} (${p.no}): negative Menge auf dem Beleg — ` +
             `Vorzeichen entsteht aus der Belegart, nicht aus dem Druck`);
    return;
  }

  const qty = Math.abs(p.qty);

  if (typeof p.kg !== "number") {
    // Altbelege (AF) drucken keine Gewichtsspalte. Dort ist stueck x gramm die
    // EINZIGE Quelle — es gibt nichts zu kreuzen. Menge (kg) muss trotzdem
    // gefuellt sein, sonst fehlt in Warenkosten der Term Menge(kg) x Einkauf/kg
    // und der Kostenanteil faellt zu niedrig aus.
    p.kg = Math.round(qty * p.grams) / 1000;
    hints.push(`Pos ${p.pos} (${p.no}): kg nicht gedruckt, aus ${qty} x ${p.grams}g abgeleitet = ${p.kg} kg`);
    p.qty = qty * sign;
    p.kg     = p.kg   * sign;
    return;
  }

  // kg ist gedruckt -> Kreuzprobe bleibt scharf.
  // Ganzzahl-Gramm statt Float: der Beleg rundet kg auf 2 Nachkommastellen,
  // zulaessige Abweichung ist die halbe Rundungsstufe = 5 g.
  if (Math.abs(qty * p.grams - Math.round(Math.abs(p.kg) * 1000)) > 5) {
    errors.push(`Pos ${p.pos} (${p.no}): ${qty} × ${p.grams}g = ` +
             `${(qty * p.grams / 1000).toFixed(3)} kg, Beleg sagt ${p.kg} kg`);
    return;
  }

  // Vorzeichen erst NACH allen Pruefungen setzen — die Kreuzprobe rechnet auf
  // Betraegen, die Buchung braucht die Richtung.
  p.qty = qty            * sign;
  p.kg     = Math.abs(p.kg)    * sign;
});

if (isReturn && errors.length === 0) {
  hints.push(`Rueckholung — ${positions.length} Position(en) werden negativ gebucht, ` +
            `bewertet zum gleitenden Durchschnitts-EK des Bestands`);
}

// ── 6) Fertige Texte fuer ⚙ Fehler ──────────────────────────────────────────
const errorText = errors.join(" · ");
const note      = hints.length ? "Hinweise: " + hints.join(" · ") : "";
const dupText    = ul
  ? `Duplikat von ${ul} — diesen Datensatz loeschen`
  : "Duplikat — Belegnummer existiert bereits, diesen Datensatz loeschen";

return { ok: errors.length === 0, ul, date, store, customer_no, kind, person,
         positions, fixtures,
         signature, signed,
         errors: errors, hints: hints, errorText, note, dupText };

// Store-Zuordnung, zweistufig: Kunden-Nr. zuerst, Name als Fallback.
// Input:  kandidaten = Array aus Modul 33 (Array Aggregator).
//         ACHTUNG: Der Aggregator kann Schluesselnamen NICHT umbenennen —
//         die Keys sind die Feld-IDs aus Modul 5 (useColumnId = true).
//         Beim Umbau von Stores muessen die Konstanten unten mit.
//         kundennr = Kunden-Nr. vom Beleg (Modul 4), nur Ziffern
//         gesucht  = Store-Name vom Beleg (Modul 4)
// Output: ok / id / name / nummer / via / warnung / fehler
//         + place_id / chat_id / stadtteil_id / shopify_gid
// Wirft NICHT — bei 0 oder >1 Treffern muss das Verdikt noch schreiben koennen.
//
// Warum die Nummer zuerst: Sie steht auf Uebergabe- UND Rueckholprotokoll in
// der Kopfzeile. Der Name kam bisher aus der "als Kommissionaer"-Zeile der
// Unterschriftsseite — die es auf Rueckholprotokollen gar nicht gibt.

const FIELD_NAME      = "fld7fbRS1BHvrqJrj";   // Stores: Name
const FIELD_NUMBER    = "fldL1YaDEswIZNnNP";   // Stores: Nummer (Primary)
const FIELD_PLACE     = "fldQ6BHP9c9FlVZE1";   // Stores: ⚙ Google Place ID
const FIELD_TG        = "fld09mGXJrafZXyjN";   // Stores: ⚙ Telegram ID (Stadt) — Lookup, Array
const FIELD_DISTRICT = "fldjVrpQh4LqaxqOk";   // Stores: Stadtteil — Link, Array
const FIELD_SHOP_GID  = "fldE7ux5MwwvJGJZl";   // Stores: ⚙ Shopify GID (nackt numerisch)

const norm = s => String(s == null ? "" : s)
  .toLowerCase()
  .replace(/[\u2018\u2019\u201A\u201B\u2032\u00B4\u0060']/g, "")
  .replace(/[\u201C\u201D\u201E\u201F\u2033"]/g, "")
  .replace(/[.,;:!?&+()\[\]{}\/\\_\u2013\u2014-]/g, " ")
  .replace(/\s+/g, " ")
  .trim();

const asArray = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === "string" && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; }
    catch (e) { return []; }
  }
  return [];
};

// Lookup-/Link-Felder liefern ein Array; ein einzelner Skalar kommt auch vor.
// Erstes Element gewinnt, leer bleibt leerer String — nie undefined, sonst
// bricht das Mapping in nachgelagerten Modulen.
const firstValue = v => {
  if (Array.isArray(v)) return v.length ? String(v[0] == null ? "" : v[0]).trim() : "";
  if (v == null) return "";
  const s = String(v).trim();
  if (s.startsWith("[")) { const a = asArray(s); return a.length ? String(a[0]).trim() : ""; }
  return s;
};

const digitsOnly = v => String(v == null ? "" : v).replace(/\D/g, "");

const EMPTY = {
  ok: false, id: null, name: null, number: null, via: null, warning: "",
  place_id: "", chat_id: "", district_id: "", shopify_gid: ""
};

const number  = digitsOnly(input.customer_no);
const wanted = norm(input.wanted);

if (!number && !wanted) {
  return Object.assign({}, EMPTY, {
    error: "Weder Kunden-Nr. noch Store-Name im Extrakt — Store nicht bestimmbar" });
}

const candidates = asArray(input.candidates).filter(k => k && k.id && k[FIELD_NAME]);
if (candidates.length === 0) {
  return Object.assign({}, EMPTY, {
    error: `Store-Liste ist leer oder ohne Namensfeld ${FIELD_NAME} — Aggregator in Modul 33 pruefen` });
}

const match = t => ({
  ok: true, id: t.id, name: t[FIELD_NAME], number: t[FIELD_NUMBER], error: "",
  place_id:     firstValue(t[FIELD_PLACE]),
  chat_id:      firstValue(t[FIELD_TG]),
  district_id: firstValue(t[FIELD_DISTRICT]),
  shopify_gid:  firstValue(t[FIELD_SHOP_GID])
});

// ── Stufe 1: Kunden-Nr. ─────────────────────────────────────────────────────
if (number) {
  const byNumber = candidates.filter(k => digitsOnly(k[FIELD_NUMBER]) === number);

  if (byNumber.length > 1) {
    return Object.assign({}, EMPTY, {
      error: `Kunden-Nr. ${number} trifft ${byNumber.length} Stores — Nummern in Stores eindeutig machen` });
  }

  if (byNumber.length === 1) {
    const t = byNumber[0];
    // Kreuzprobe: Nummer gewinnt, aber ein abweichender Name ist ein Signal —
    // entweder Store umbenannt oder falscher Beleg. Blockt nicht, wird im
    // Verdikt als Hinweis mitgeschrieben.
    const warning = (wanted && norm(t[FIELD_NAME]) !== wanted)
      ? `Kunden-Nr. ${number} zeigt auf "${t[FIELD_NAME]}", der Beleg nennt "${input.wanted}" — Nummer hat entschieden`
      : "";
    return Object.assign({}, match(t), { via: "nummer", warning });
  }

  // Nummer gelesen, aber kein Store dazu: nicht still auf den Namen
  // ausweichen — eine unbekannte Kunden-Nr. ist ein eigener Befund.
  return Object.assign({}, EMPTY, {
    error: `Kunden-Nr. ${number} nicht in Stores gefunden — Lexware ID im Store pflegen oder Store anlegen` });
}

// ── Stufe 2: Name ───────────────────────────────────────────────────────────
const byName = candidates.filter(k => norm(k[FIELD_NAME]) === wanted);

if (byName.length === 1) {
  const t = byName[0];
  if (!t[FIELD_NUMBER]) {
    return Object.assign({}, EMPTY, {
      error: `Store "${input.wanted}" hat keine Store-Nummer — Bestands-Schluessel nicht bildbar` });
  }
  return Object.assign({}, match(t), {
    via: "name",
    warning: `Store ueber den Namen aufgeloest — Kunden-Nr. war auf dem Beleg nicht lesbar`
  });
}

if (byName.length === 0) {
  return Object.assign({}, EMPTY, {
    error: `Store "${input.wanted}" nicht in Stores gefunden — Store anlegen oder Namen abgleichen` });
}

return Object.assign({}, EMPTY, {
  error: `Store "${input.wanted}" trifft ${byName.length} Eintraege: ` +
          `${byName.map(t => t[FIELD_NAME]).join(", ")} — Namen in Stores eindeutig machen` });

// Identität und Konditionen AM LEISTUNGSDATUM — nie am Run-Zeitpunkt.
// Input:  person      = "Uebergeben durch" / "Abgeholt durch" (Modul 4)
//         datum       = YYYY-MM-DD (Modul 4, bereits normalisiert)
//         vertriebler = records[] aus Modul 22 (Airtable REST, ein Bundle)
//         konditionen = records[] aus Modul 24 (Airtable REST, ein Bundle)
// Output: vertriebler_ok / vertriebler_id / vertriebler_name / vertriebler_fehler
//         besteuerung / datum
//         kondition_id / kondition_name / kondition_fehler
//
// Warum drei Schritte in einem Modul: Vertriebler -> Besteuerung -> Kondition
// ist eine Kette, in der jeder Schritt den naechsten speist. Getrennte Module
// braeuchten je eine neue Modul-ID; neue IDs mit Airtable-Connection werden
// vom Blueprint-Import verworfen, weil ihnen das restore-Objekt fehlt.
//
// Warum REST-Calls (Modul 22/24) statt Search + Aggregator: makeApiCall liefert
// IMMER genau ein Bundle — auch bei leerer Liste. Ein Search-Modul erzeugt pro
// Treffer ein Bundle (alle Folgemodule liefen mehrfach) und bei null Treffern
// gar keines, womit der Lauf still endet, bevor Modul 44 "Fehlerhaft" schreibt.
//
// Wirft NICHT: das Modul laeuft vor dem Verdikt. Ein Throw wuerde den Lauf
// abbrechen, bevor der Status geschrieben werden kann — der Beleg bliebe stumm
// in der Inbox liegen.

const V_NAME    = "fldhDp2HHI6BxjlZq";   // Vertriebler: Name
const V_REGULAR_FROM = "fldF4idsFUiCgAX1A";   // Vertriebler: Regelbesteuerung ab
const K_NAME    = "fldSuQBQxDERrPx38";   // Konditionen: ID (Primary)
const K_AB      = "fldLCQhky7QB1uZ20";   // Konditionen: Gültig ab
const K_FOR    = "fldJmJuFo4eDbNvP3";   // Konditionen: Gültig für

const ISO = /^\d{4}-\d{2}-\d{2}$/;

const asArray = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === "string" && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; }
    catch (e) { return []; }
  }
  return [];
};

// Airtable-REST verschachtelt die Werte unter .fields (returnFieldsByFieldId).
const field = (k, f) => (k && k.fields ? k.fields[f] : k ? k[f] : undefined);

// singleSelect kommt je nach Quelle als String oder als {name}.
const asText = v => {
  if (v == null) return "";
  if (Array.isArray(v)) return v.length ? asText(v[0]) : "";
  if (typeof v === "object") return String(v.name == null ? "" : v.name).trim();
  return String(v).trim();
};

const norm = s => String(s == null ? "" : s)
  .toLowerCase()
  .replace(/[\u2018\u2019\u201A\u201B\u2032\u00B4\u0060']/g, "")
  .replace(/[\u201C\u201D\u201E\u201F\u2033"]/g, "")
  .replace(/[.,;:!?&+()\[\]{}\/\\_\u2013\u2014-]/g, " ")
  .replace(/\s+/g, " ")
  .trim();

const EMPTY = {
  salesperson_ok: false, salesperson_id: null, salesperson_name: null,
  salesperson_error: "",
  taxation: null, date: null,
  condition_id: null, condition_name: null, condition_error: ""
};

// ── 1) Vertriebler aus dem Beleg ────────────────────────────────────────────
// Der Name steuert Besteuerung -> Kondition -> Kostenanteil. Deshalb exakter
// Vergleich auf normalisierter Form, KEINE Fuzzy-Suche, KEIN Default. Im
// Zweifel Fehler — eine falsche Zuordnung dreht Geld.
const wanted = norm(input.person);
if (!wanted) {
  return Object.assign({}, EMPTY, {
    salesperson_error: "Uebergeben/Abgeholt durch fehlt im Extrakt — " +
                        "Vertriebler nicht bestimmbar" });
}

const vCandidates = asArray(input.salespeople)
  .filter(k => k && k.id && field(k, V_NAME));

if (vCandidates.length === 0) {
  return Object.assign({}, EMPTY, {
    salesperson_error: `Vertriebler-Liste ist leer oder ohne Namensfeld ${V_NAME} — Modul 22 pruefen` });
}

const vMatches = vCandidates.filter(k => norm(field(k, V_NAME)) === wanted);

if (vMatches.length === 0) {
  return Object.assign({}, EMPTY, {
    salesperson_error: `Vertriebler "${input.person}" nicht gefunden — Schreibweise auf dem ` +
                        `Beleg muss zeichengenau zum Namen in Vertriebler passen` });
}
if (vMatches.length > 1) {
  return Object.assign({}, EMPTY, {
    salesperson_error: `Vertriebler "${input.person}" trifft ${vMatches.length} Eintraege: ` +
                        `${vMatches.map(t => asText(field(t, V_NAME))).join(", ")} — Namen eindeutig machen` });
}

const v = vMatches[0];
const base = {
  salesperson_ok: true,
  salesperson_id: v.id,
  salesperson_name: asText(field(v, V_NAME)),
  salesperson_error: ""
};

// ── 2) Besteuerung ──────────────────────────────────────────────────────────
const date = String(input.date || "").slice(0, 10);
if (!ISO.test(date)) {
  return Object.assign({}, EMPTY, base, {
    condition_error: "Leistungsdatum fehlt oder ist nicht YYYY-MM-DD — " +
                      "Kondition nicht bestimmbar" });
}

// Leeres "Regelbesteuerung ab" = durchgehend Kleinunternehmer.
let taxation = "Kleinunternehmer";
const regularFrom = asText(field(v, V_REGULAR_FROM)).slice(0, 10);
// Lexikografischer Vergleich ist auf YYYY-MM-DD chronologisch korrekt.
if (ISO.test(regularFrom) && date >= regularFrom) taxation = "Regelbesteuerung";

// ── 3) Konditionsversion ────────────────────────────────────────────────────
// Zeichengenauer Vergleich auf "Gueltig fuer" — der Wert muss exakt zur
// Besteuerung passen, sonst ist es nicht die richtige Version.
const candidates = asArray(input.conditions)
  .filter(k => k && k.id && asText(field(k, K_FOR)) === taxation)
  .map(k => ({ id: k.id,
               name: asText(field(k, K_NAME)),
               from: asText(field(k, K_AB)).slice(0, 10) }))
  .filter(k => ISO.test(k.from) && k.from <= date)
  .sort((a, b) => (a.from < b.from ? 1 : a.from > b.from ? -1 : 0));

if (candidates.length === 0) {
  return Object.assign({}, EMPTY, base, { taxation, date,
    condition_error: `Keine Konditionsversion fuer "${taxation}" mit ` +
                      `Gueltig ab <= ${date} gefunden — Version anlegen` });
}

// Zwei Versionen mit identischem "Gueltig ab" fuer dieselbe Besteuerung sind
// nicht entscheidbar — lieber blocken als die falsche greifen lassen.
if (candidates.length > 1 && candidates[0].from === candidates[1].from) {
  return Object.assign({}, EMPTY, base, { taxation, date,
    condition_error: `Zwei Konditionsversionen fuer "${taxation}" ab ${candidates[0].from}: ` +
                      `${candidates[0].name}, ${candidates[1].name} — Gueltig ab eindeutig machen` });
}

return Object.assign({}, base, {
  taxation, date,
  condition_id: candidates[0].id,
  condition_name: candidates[0].name,
  condition_error: ""
});

// pos-restock — Konsolidiertes Verdikt
// Kaskade Parser -> Store -> Vertriebler -> Kondition -> Dedup,
// erstes Fehlerkriterium gewinnt.
// Ein sauberes ok-Boolean fuer den nachgelagerten Filter auf #26.
//
// Vertriebler und Kondition sind hier drin, weil beide den Kostenanteil
// bestimmen. Faellt eines von beiden aus, darf die Lieferung nicht als
// "Abgeschlossen" durchlaufen — sonst entsteht eine Lieferung ohne
// Konditionsbezug, deren Kostenanteil still auf null rechnet.
const truthy = v => v === true || v === "true";
const parserOk = truthy(input.parser_ok);
const storeOk  = truthy(input.store_ok);
const salesOk  = truthy(input.salesperson_ok);
const condId   = input.condition_id;
const condOk   = !!(condId && String(condId).trim());
const condError = String(input.condition_error || "").trim();
const dupId    = input.dup_id;
const dup      = !!(dupId && String(dupId).trim());

let ok, note;
if (!parserOk)     { ok = false; note = input.errorText || "Parser: unbekannter Fehler"; }
else if (!storeOk) { ok = false; note = input.store_error || "Store nicht eindeutig aufgeloest"; }
else if (!salesOk) { ok = false; note = input.salesperson_error || "Vertriebler nicht eindeutig aufgeloest"; }
else if (!condOk)  { ok = false; note = condError || "Keine Kondition zum Leistungsdatum gefunden"; }
else if (dup)      { ok = false; note = input.dupText || "Duplikat"; }
else {
  ok = true;
  // Nicht-blockende Befunde sammeln: Parser-Hinweise plus die Store-Kreuzprobe
  // (Kunden-Nr. und Name zeigen auf verschiedene Stores).
  const parts = [];
  if (input.store_warning && String(input.store_warning).trim()) {
    parts.push(String(input.store_warning).trim());
  }
  if (input.note && String(input.note).trim()) {
    parts.push(String(input.note).trim());
  }
  note = parts.join(" · ");
}

return {
  ok,
  status: ok ? "In Bearbeitung" : "Fehlerhaft",
  note,
  signed: truthy(input.signed)
};

// Kommissionsware und Ausstattung wieder zu EINER Liste zusammenfuehren.
// Modul 4 trennt sie fachlich korrekt — geschrieben werden muessen aber beide,
// weil die Ausstattungszeile die Inventarkosten der Lieferung traegt.
// Output: alle[] nach Positionsnummer sortiert + anzahl fuer das Zaehl-Gate.

const norm = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === "string" && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; }
    catch (e) { return []; }
  }
  return [];
};

const all = norm(input.positions)
  .concat(norm(input.fixtures))
  .sort((a, b) => Number(a.pos) - Number(b.pos));

if (all.length === 0) throw new Error("Keine Positionen zum Schreiben");

return { all, count: all.length };

// Stall-Fallback: welche Positionen wurden NICHT aufgeloest?
// alle = alle erwarteten Zeilen (#26), resolved = aufgeloeste Zeilen (#8.array)
const arr = v => Array.isArray(v) ? v : [];
const expected = arr(input.all).map(p => Number(p.pos));
const mapped  = new Set(arr(input.resolved).map(r => Number(r.pos)));
const missing  = expected.filter(p => !mapped.has(p));
return {
  missing,
  count: missing.length,
  note: "Positionen nicht aufloesbar (Produkt/Preis/Bestand/EK fehlt): "
           + (missing.length ? missing.join(", ") : "unbekannt")
};
